    adjacencyList[startVertex].add(new Edge(startVertex, endVertex, 1));
    if(!isDirected && startVertex != endVertex) {
    	adjacencyList[endVertex].add(new Edge(endVertex, startVertex, 1));
    }
    this.numberOfEdges += 1;
